"""Rebuild the standalone notebook set from pap_colab_protocol.py."""
from pathlib import Path
import nbformat as nbf
root=Path(__file__).parent
helper=(root/'pap_colab_protocol.py').read_text()
COPY='Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary. Licensed under GNU GPL v3.0. Third-party dependencies retain their own licenses.'
def C(s): return nbf.v4.new_code_cell(s)
def M(s): return nbf.v4.new_markdown_cell(s)
def build(filename,title,summary,cells,gpu='NONE'):
    nb=nbf.v4.new_notebook()
    nb.metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3'},'colab':{'name':filename,'provenance':[],'gpuType':gpu,'include_colab_link':True},'pap':{'copyright':COPY,'license':'GPL-3.0-only','platform':'Physical AI Platform','notebook_version':'1.0.0','runtime':'Google Colab browser-hosted Python','evidence':'SIMULATED/UNVERIFIED','author':'Abhishek Choudhary','affiliation':'AyeAI','orcid':'https://orcid.org/0009-0002-0684-8320'}}
    nb.cells=[M(f'# {title}\n\n{COPY}\n\n{summary}\n\n**Deployment:** browser-only platform; this notebook runs in a user-controlled Colab runtime. GPU/TPU availability is variable and not guaranteed. **Evidence boundary:** results remain `SIMULATED` and `UNVERIFIED`; this is not HIL or physical verification.'),M('## 0. Runtime, security and provenance\nRun cells in order. The notebook records backend versions, solver settings, runtime device, model configuration, timestamps and SHA-256 job/result digests. Results must be imported through the separate PAP Colab Bridge. Never upload untrusted native FMUs or binaries.'),C(helper),*cells]
    nbf.write(nb,root/filename)

build('01_scipy_solver_validation.ipynb','PAP Emulation - SciPy Solver Validation','Linear state-space execution with six SciPy integration methods, analytical comparison and a cryptographically bound PAP job/result exchange.',[
 C("# Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary.\n# SPDX-License-Identifier: GPL-3.0-only\n%pip -q install 'numpy>=1.26,<3' 'scipy>=1.11,<2'"),
 C("import json, hashlib, platform, sys, time\nimport numpy as np\nimport scipy\nfrom scipy.integrate import solve_ivp\nprint({'python':sys.version,'platform':platform.platform(),'numpy':np.__version__,'scipy':scipy.__version__})\nPAP_USE_DEMO_JOB=True  # Set False to upload one browser-exported PAP job JSON\ndefault_inputs={'A':[[-1.0]],'B':[[1.0]],'u':[1.0],'x0':[0.0],'C':[[1.0]],'D':[[0.0]],'times':np.linspace(0.0,5.0,51).tolist(),'method':'DOP853','rtol':1e-9,'atol':1e-11}\njob,job_is_demo=pap_get_job('scipy.solve_ivp','scipy.linear_ode',default_inputs,PAP_USE_DEMO_JOB)\ninputs=job['inputs']; A=np.asarray(inputs['A'],float); B=np.asarray(inputs['B'],float); u=np.asarray(inputs['u'],float); x0=np.asarray(inputs['x0'],float); Cmat=np.asarray(inputs['C'],float); D=np.asarray(inputs.get('D',np.zeros((Cmat.shape[0],B.shape[1]))),float); times=np.asarray(inputs['times'],float)\nif A.ndim!=2 or A.shape[0]!=A.shape[1] or B.ndim!=2 or B.shape[0]!=A.shape[0] or u.shape!=(B.shape[1],) or x0.shape!=(A.shape[0],) or Cmat.ndim!=2 or Cmat.shape[1]!=A.shape[0] or D.shape!=(Cmat.shape[0],B.shape[1]): raise ValueError('Invalid state-space matrix dimensions')\nif times.ndim!=1 or len(times)<2 or not np.isfinite(times).all() or np.any(np.diff(times)<=0): raise ValueError('times must be finite and strictly increasing')\nrtol=float(inputs.get('rtol',1e-9)); atol=float(inputs.get('atol',1e-11)); print('Verified job',job['jobId'],'samples',len(times))"),
 M('## 1. Execute solver comparison\nThe fixture solves `dx/dt = A x + B u`, `y = C x + D u`. For the default scalar fixture, the analytical solution is `x(t)=1-exp(-t)`. All six methods must converge and agree with the analytical reference within the stated threshold.'),
 C("def rhs(t,x): return A@x+B@u\nmethods=['RK23','RK45','DOP853','Radau','BDF','LSODA']; solver_results={}\nfor method in methods:\n    sol=solve_ivp(rhs,(float(times[0]),float(times[-1])),x0,method=method,t_eval=times,rtol=rtol,atol=atol)\n    if not sol.success or sol.y.shape!=(A.shape[0],len(times)) or not np.isfinite(sol.y).all(): raise RuntimeError(f'{method} failed: {sol.message}')\n    y=(Cmat@sol.y+(D@u)[:,None]).T\n    solver_results[method]={'nfev':int(sol.nfev),'njev':int(sol.njev),'nlu':int(sol.nlu),'termination':str(sol.message)}\n    if A.shape==(1,1) and np.allclose(A,[[-1]]) and np.allclose(B,[[1]]) and np.allclose(u,[1]) and np.allclose(x0,[0]):\n        err=np.abs(sol.y[0]-(1-np.exp(-(times-times[0])))); solver_results[method]['max_abs_error_analytical']=float(err.max()); assert err.max()<2e-8,(method,err.max())\nsolver_results"),
 M('## 2. Export result\nThe result is bound to the exact uploaded job digest. Demo mode also downloads the matching job file so the result can be independently imported and checked by the browser bridge.'),
 C("method=inputs.get('method','DOP853'); chosen=solve_ivp(rhs,(float(times[0]),float(times[-1])),x0,method=method,t_eval=times,rtol=rtol,atol=atol)\ny=(Cmat@chosen.y+(D@u)[:,None]).T\noutputs=[{'sequence':int(i),'time':float(t),'values':{'state':chosen.y[:,i].astype(float).tolist(),'output':y[i].astype(float).tolist()}} for i,t in enumerate(times)]\nresult=pap_make_result(job,'scipy.solve_ivp',scipy.__version__,outputs,{'success':bool(chosen.success),'method':method,'rtol':rtol,'atol':atol,'nfev':int(chosen.nfev),'crossMethodValidation':solver_results},'cpu')\npap_export(job,result,job_is_demo)\nprint('Exported',len(outputs),'time samples; outcome remains simulated/unverified.')")
])

build('02_fmi_fmpy_colab.ipynb','PAP Emulation - FMI / FMPy','FMI 1.0/2.0/3.0 model-description inspection and FMU execution using FMPy. Exports normalized time-series values while requiring a separate typed SIR port mapping.',[
 C("# Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary.\n# SPDX-License-Identifier: GPL-3.0-only\n%pip -q install 'fmpy[complete]' 'numpy>=1.26,<3'"),
 C("import os, json, hashlib, platform, sys\nimport numpy as np, fmpy\nfrom fmpy import read_model_description, simulate_fmu\nprint({'python':sys.version,'platform':platform.platform(),'fmpy':getattr(fmpy,'__version__','unknown')})\nPAP_USE_DEMO_JOB=True\ndefault_inputs={'startTime':0.0,'stopTime':1.0,'outputInterval':0.01,'outputVariables':[]}\njob,job_is_demo=pap_get_job('fmpy.fmi','fmpy.simulate',default_inputs,PAP_USE_DEMO_JOB)"),
 M('## 1. Upload one trusted FMU\nFMUs can contain native executable code. Only use trusted FMUs in a disposable runtime. Colab is not asserted to be a hardened sandbox for hostile native binaries.'),
 C("from google.colab import files\nuploaded=files.upload(); fmus=[name for name in uploaded if name.lower().endswith('.fmu')]\nif len(fmus)!=1: raise ValueError('Upload exactly one trusted .fmu file')\nfmu_path=fmus[0]; fmu_sha=hashlib.sha256(open(fmu_path,'rb').read()).hexdigest(); md=read_model_description(fmu_path)\nprint({'sha256':fmu_sha,'fmiVersion':md.fmiVersion,'modelName':md.modelName,'guid':md.guid,'hasCoSimulation':bool(md.coSimulation),'hasModelExchange':bool(md.modelExchange)})"),
 M('## 2. Inspect, simulate and export\nReview causality, units, variability and value references. The raw result cannot be treated as canonical until the adapter maps each FMU variable to a SIR port, unit and coordinate frame.'),
 C("variables=[v.name for v in md.modelVariables if v.causality=='output']\nif not variables: raise ValueError('FMU has no output variables')\nselected=job['inputs'].get('outputVariables') or variables[:min(8,len(variables))]\nif set(selected)-set(variables): raise ValueError('Requested FMU output name is not declared')\nstart=float(job['inputs'].get('startTime',0)); stop=float(job['inputs'].get('stopTime',1)); interval=float(job['inputs'].get('outputInterval',0.01))\nif not stop>start or interval<=0: raise ValueError('Invalid start/stop/output interval')\ndata=simulate_fmu(fmu_path,start_time=start,stop_time=stop,output=selected,output_interval=interval)\nif len(data)==0: raise RuntimeError('FMU returned no samples')\noutputs=[]\nfor i,row in enumerate(data):\n    values={name:float(row[name]) for name in selected}\n    if not np.isfinite(list(values.values())).all(): raise RuntimeError('FMU produced non-finite output')\n    outputs.append({'sequence':int(i),'time':float(row['time']),'values':values})\nresult=pap_make_result(job,'fmpy.fmi',getattr(fmpy,'__version__','unknown'),outputs,{'fmiVersion':md.fmiVersion,'modelName':md.modelName,'guid':md.guid,'fmuSha256':fmu_sha,'selectedVariables':selected,'mappingRequired':True},'cpu')\npap_export(job,result,job_is_demo,'pap-fmpy-result.json')")
])

build('03_pybamm_battery_colab.ipynb','PAP Emulation - PyBaMM Battery Models','SPM, SPMe and DFN electrochemical battery model execution, parameter-set provenance, solver diagnostics and optional JAX device discovery.',[
 C("# Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary.\n# SPDX-License-Identifier: GPL-3.0-only\n%pip -q install 'pybamm>=24.11' 'numpy>=1.26,<3'"),
 C("import json, hashlib, platform, sys, numpy as np, pybamm\nprint({'python':sys.version,'platform':platform.platform(),'pybamm':pybamm.__version__})\nPAP_USE_DEMO_JOB=True\ndefault_inputs={'modelName':'SPM','parameterSet':'Chen2020','stopTimeSeconds':1800.0,'sampleCount':181}\njob,job_is_demo=pap_get_job('pybamm.battery','pybamm.simulate',default_inputs,PAP_USE_DEMO_JOB)"),
 M('## 1. Select electrochemical model fidelity\nSPM is reduced-order; SPMe adds electrolyte dynamics; DFN is the Doyle-Fuller-Newman pseudo-two-dimensional model. They have different assumptions and computational cost. Cross-model agreement is not physical validation.'),
 C("name=job['inputs'].get('modelName','SPM'); model_ctor={'SPM':pybamm.lithium_ion.SPM,'SPMe':pybamm.lithium_ion.SPMe,'DFN':pybamm.lithium_ion.DFN}.get(name)\nif model_ctor is None: raise ValueError('modelName must be SPM, SPMe or DFN')\nmodel=model_ctor(); parameter_set=job['inputs'].get('parameterSet','Chen2020'); params=pybamm.ParameterValues(parameter_set)\nsolver=pybamm.CasadiSolver(mode='safe'); sim=pybamm.Simulation(model,parameter_values=params,solver=solver)\nstop=float(job['inputs'].get('stopTimeSeconds',1800)); count=int(job['inputs'].get('sampleCount',181))\nif stop<=0 or count<2 or count>100001: raise ValueError('Invalid stopTimeSeconds/sampleCount')\nsolution=sim.solve(t_eval=np.linspace(0,stop,count)); print('termination=',solution.termination,'samples=',len(solution.t))"),
 M('## 2. Accelerator probe and result export\nThe PyBaMM simulation above uses CasADi and is labelled CPU. JAX device discovery is informative only; it does not mean this solve used a GPU. A separate JAX-compatible solver and model path must be explicitly configured and validated before claiming GPU execution.'),
 C("gpu={'jaxInstalled':False,'devices':[],'usedByThisSolve':False}\ntry:\n import jax; gpu={'jaxInstalled':True,'devices':[str(d) for d in jax.devices()],'backend':jax.default_backend(),'usedByThisSolve':False}\nexcept Exception as e: gpu['error']=str(e)\nvars=['Terminal voltage [V]','Current [A]','X-averaged cell temperature [K]']; obs={}\nfor var in vars:\n try:\n  arr=np.asarray(solution[var].entries).reshape(-1)\n  if np.isfinite(arr).all(): obs[var]=arr.tolist()\n except KeyError: pass\nif not obs: raise RuntimeError('No expected observables found; inspect the selected model variables')\noutputs=[{'sequence':int(i),'time':float(t),'values':{k:float(v[i]) for k,v in obs.items()}} for i,t in enumerate(solution.t)]\nresult=pap_make_result(job,'pybamm.battery',pybamm.__version__,outputs,{'model':name,'parameterSet':parameter_set,'solver':'CasadiSolver','termination':str(solution.termination),'acceleratorProbe':gpu,'mappingRequired':True},'cpu')\npap_export(job,result,job_is_demo,'pap-pybamm-result.json')")
])

build('04_mujoco_mjx_gpu_colab.ipynb','PAP Emulation - MuJoCo MJX GPU/TPU Lab','Vectorized articulated-body dynamics using the official MuJoCo MJX/JAX API. Runs on supported CPU/GPU/TPU hardware and records the actual JAX backend.',[
 C("# Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary.\n# SPDX-License-Identifier: GPL-3.0-only\n%pip -q install 'mujoco>=3.2' 'mujoco-mjx>=3.2'"),
 C("import sys, platform, time, jax, jax.numpy as jnp, mujoco\nfrom mujoco import mjx\nprint({'python':sys.version,'platform':platform.platform(),'mujoco':mujoco.__version__,'jax':jax.__version__,'devices':[str(d) for d in jax.devices()]})\nPAP_USE_DEMO_JOB=True\ndefault_inputs={'environmentCount':256,'steps':250,'dt':0.002,'angleMin':-0.5,'angleMax':0.5}\njob,job_is_demo=pap_get_job('mujoco.mjx','mujoco.mjx.batch_pendulum',default_inputs,PAP_USE_DEMO_JOB)"),
 M('## 1. MJX-JAX vectorized pendulum\nMJX-JAX supports JAX/XLA compute devices, including supported NVIDIA/AMD GPUs and Google Cloud TPUs. MJX-Warp is an alternative NVIDIA GPU implementation with different feature and autodiff trade-offs. This notebook uses the documented MJX-JAX `put_model`, `make_data`, `step`, `vmap` and `jit` path.'),
 C("xml='''<mujoco model=\"pap-pendulum\"><option timestep=\"0.002\" gravity=\"0 0 -9.81\"/><worldbody><body name=\"bob\"><joint name=\"hinge\" type=\"hinge\" axis=\"0 1 0\"/><geom type=\"capsule\" fromto=\"0 0 0 0 0 -1\" size=\"0.04\" mass=\"1\"/></body></worldbody></mujoco>'''\nmjm=mujoco.MjModel.from_xml_string(xml); model=mjx.put_model(mjm)\nN=int(job['inputs'].get('environmentCount',256)); steps=int(job['inputs'].get('steps',250)); dt=float(job['inputs'].get('dt',mjm.opt.timestep))\nif N<1 or N>100000 or steps<1 or steps>100000 or abs(dt-mjm.opt.timestep)>1e-12: raise ValueError('Invalid environment count/step count/timestep')\nangles=jnp.linspace(float(job['inputs'].get('angleMin',-0.5)),float(job['inputs'].get('angleMax',0.5)),N,dtype=jnp.float32)\n@jax.vmap\ndef simulate_one(angle):\n data=mjx.make_data(model)\n data=data.replace(qpos=data.qpos.at[0].set(angle))\n data=jax.lax.fori_loop(0,steps,lambda i,d:mjx.step(model,d),data)\n return data.qpos[0],data.qvel[0]\ncompiled=jax.jit(simulate_one); started=time.time(); qpos,qvel=compiled(angles); jax.block_until_ready(qpos); elapsed=time.time()-started\nassert bool(jnp.isfinite(qpos).all()) and bool(jnp.isfinite(qvel).all())\nprint({'environments':N,'steps':steps,'elapsedSeconds':elapsed,'jaxBackend':jax.default_backend(),'finalQposRange':[float(jnp.min(qpos)),float(jnp.max(qpos))]})"),
 M('## 2. Result export and validation boundary\nThis is a numerical execution smoke case, not a calibrated mechanism validation. Production validation requires energy drift, timestep refinement, constraint/contact benchmarks and documented MJX feature parity for the model being used.'),
 C("outputs=[{'sequence':0,'time':float(steps*dt),'values':{'qposMin':float(jnp.min(qpos)),'qposMax':float(jnp.max(qpos)),'qvelMin':float(jnp.min(qvel)),'qvelMax':float(jnp.max(qvel))}}]\nresult=pap_make_result(job,'mujoco.mjx',mujoco.__version__,outputs,{'model':'single-hinge-pendulum','environmentCount':N,'steps':steps,'dt':dt,'elapsedSeconds':elapsed,'jaxVersion':jax.__version__,'jaxBackend':jax.default_backend(),'devices':[str(d) for d in jax.devices()],'gpuOrTpuUsed':jax.default_backend()!='cpu'},jax.default_backend())\npap_export(job,result,job_is_demo,'pap-mjx-result.json')")
],gpu='GPU')

build('05_ngspice_circuit_colab.ipynb','PAP Emulation - ngspice Circuit Transient','A native ngspice RC transient simulation validated against the analytical first-order circuit response and exported through the common PAP result contract.',[
 C("# Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary.\n# SPDX-License-Identifier: GPL-3.0-only\n!apt-get -qq update && apt-get -qq install -y ngspice"),
 C("import subprocess, pathlib, math, json, hashlib\nversion=subprocess.run(['ngspice','--version'],capture_output=True,text=True,check=True).stdout\nprint(version.splitlines()[:8])\nPAP_USE_DEMO_JOB=True\ndefault_inputs={'resistanceOhm':1000.0,'capacitanceFarad':1e-6,'stopTimeSeconds':0.005,'sampleStepSeconds':5e-5}\njob,job_is_demo=pap_get_job('ngspice','ngspice.rc_transient',default_inputs,PAP_USE_DEMO_JOB)"),
 M('## 1. RC transient analytical benchmark\nA 1 V step drives R and C. The ideal capacitor response is `1-exp(-t/(RC))`. The 6% error bound here is a coarse smoke-test threshold accounting for the idealized source edge and sampled transient; it is not a general SPICE accuracy qualification.'),
 C("R=float(job['inputs'].get('resistanceOhm',1000)); Cval=float(job['inputs'].get('capacitanceFarad',1e-6)); stop=float(job['inputs'].get('stopTimeSeconds',0.005)); step=float(job['inputs'].get('sampleStepSeconds',5e-5)); tau=R*Cval\nif min(R,Cval,stop,step)<=0 or stop/step>2_000_000: raise ValueError('Invalid or excessive RC request')\nnetlist=f'''PAP RC transient validation\\nVSTEP in 0 PULSE(0 1 0 1n 1n 10 20)\\nR1 in out {R}\\nC1 out 0 {Cval}\\n.control\\nset noaskquit\\ntran {step} {stop}\\nwrdata rc-transient.dat time v(out)\\nquit\\n.endc\\n.end\\n'''\npathlib.Path('pap_rc.cir').write_text(netlist)\nrun=subprocess.run(['ngspice','-b','pap_rc.cir'],capture_output=True,text=True)\nif run.returncode!=0: raise RuntimeError(run.stdout+'\\n'+run.stderr)\ndata=[]\nfor line in pathlib.Path('rc-transient.dat').read_text().splitlines():\n vals=[float(x) for x in line.split()]\n if len(vals)>=2 and all(math.isfinite(x) for x in vals): data.append((vals[0],vals[-1]))\nif len(data)<10: raise RuntimeError('Insufficient transient samples')\nerrors=[abs(v-(1-math.exp(-t/tau))) for t,v in data if t>=0]; max_error=max(errors)\nprint({'samples':len(data),'maxAbsError':max_error,'returncode':run.returncode}); assert max_error<0.06"),
 C("outputs=[{'sequence':int(i),'time':float(t),'values':{'capacitorVoltage_V':float(v)}} for i,(t,v) in enumerate(data)]\nresult=pap_make_result(job,'ngspice',version.splitlines()[0] if version.splitlines() else 'unknown',outputs,{'R_ohm':R,'C_farad':Cval,'timeConstantSeconds':tau,'maxAbsErrorAgainstAnalytical':max_error,'sampleCount':len(data),'mappingRequired':True},'cpu')\npap_export(job,result,job_is_demo,'pap-ngspice-result.json')")
])

build('06_jax_gpu_ensemble_colab.ipynb','PAP Emulation - JAX GPU/TPU Ensemble','A vectorized ODE parameter ensemble with an analytical reference. Demonstrates JAX/XLA GPU/TPU compute and records actual device use. It does not imply every domain solver is GPU accelerated.',[
 C("# Copyright © 1993-2026 Abhishek Choudhary. All rights reserved. AyeAI®, AyeAM® and AyeCNSe® are registered trademarks of Abhishek Choudhary.\n# SPDX-License-Identifier: GPL-3.0-only\n# Do not reinstall JAX blindly: preserve Colab's accelerator-enabled JAX build."),
 C("import jax, jax.numpy as jnp, time\nprint({'jax':jax.__version__,'devices':[str(d) for d in jax.devices()],'backend':jax.default_backend()})\nPAP_USE_DEMO_JOB=True\ndefault_inputs={'ensembleSize':100000,'steps':200,'dt':0.005,'kMin':0.1,'kMax':5.0}\njob,job_is_demo=pap_get_job('jax.xla','jax.ode_ensemble',default_inputs,PAP_USE_DEMO_JOB)"),
 M('## 1. Vectorized RK4 ensemble\nThe system is `dx/dt=-k*x+1` with x(0)=0. The closed-form solution is `(1-exp(-k*t))/k`. The notebook compares the vectorized fixed-step RK4 result to that reference over a parameter ensemble.'),
 C("inputs=job['inputs']; N=int(inputs.get('ensembleSize',100000)); steps=int(inputs.get('steps',200)); dt=float(inputs.get('dt',0.005)); kmin=float(inputs.get('kMin',0.1)); kmax=float(inputs.get('kMax',5.0))\nif N<1 or N>2_000_000 or steps<1 or steps>1_000_000 or dt<=0 or not 0<kmin<kmax: raise ValueError('Invalid ensemble parameters')\nk=jnp.linspace(kmin,kmax,N,dtype=jnp.float32)\ndef rhs(x,k): return -k*x+1.0\ndef rk4(x,k,dt):\n a=rhs(x,k); b=rhs(x+0.5*dt*a,k); c=rhs(x+0.5*dt*b,k); d=rhs(x+dt*c,k)\n return x+(dt/6)*(a+2*b+2*c+d)\ndef integrate(k): return jax.lax.fori_loop(0,steps,lambda i,x:rk4(x,k,dt),jnp.zeros_like(k))\ncompiled=jax.jit(integrate); started=time.time(); xfinal=compiled(k); xfinal.block_until_ready(); elapsed=time.time()-started\nif not bool(jnp.isfinite(xfinal).all()): raise RuntimeError('Non-finite state')\nreference=(1-jnp.exp(-k*steps*dt))/k; max_error=float(jnp.max(jnp.abs(xfinal-reference)))\nprint({'ensembleSize':N,'steps':steps,'elapsedSeconds':elapsed,'maxAbsError':max_error,'backend':jax.default_backend()}); assert max_error<3e-5"),
 C("outputs=[{'sequence':0,'time':float(steps*dt),'values':{'ensembleMin':float(jnp.min(xfinal)),'ensembleMax':float(jnp.max(xfinal)),'ensembleMean':float(jnp.mean(xfinal))}}]\nresult=pap_make_result(job,'jax.xla',jax.__version__,outputs,{'ensembleSize':N,'steps':steps,'dt':dt,'maxAbsErrorAgainstAnalytical':max_error,'elapsedSeconds':elapsed,'backend':jax.default_backend(),'devices':[str(d) for d in jax.devices()]},jax.default_backend())\npap_export(job,result,job_is_demo,'pap-jax-result.json')")
],gpu='GPU')

print('Built six standalone Colab notebooks.')
